// Server-rendered public changelog and the admin page.
import { esc, renderMarkdown } from "./store.mjs";
export { esc };
const color = (c) => (/^#[0-9a-fA-F]{6}$/.test(c || "") ? c : "#0f766e");

const shell = (c, title, body, head = "", robots = "") => `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">${robots}<title>${esc(title)}</title>${head}
<style>body{font:16px/1.55 system-ui,sans-serif;max-width:42rem;margin:2.5rem auto;padding:0 1rem;color:#111827}h1{color:${color(c)};font-size:1.7rem}h2{font-size:1.2rem;margin:.2rem 0}
.e{border-top:1px solid #e5e7eb;padding:1.2rem 0}.m{font-size:.85rem;color:#4b5563}.tag{display:inline-block;padding:0 .55rem;border-radius:99px;background:${color(c)};color:#fff;font-size:.75rem;font-weight:700;text-transform:uppercase;margin-right:.5rem}
code{background:#f3f4f6;padding:0 .25rem;border-radius:4px}label{display:block;font-weight:600;margin:.8rem 0 .2rem}input,textarea,select,button{font:inherit;padding:.5rem .65rem;border-radius:8px;border:1px solid #9ca3af;width:100%;box-sizing:border-box}
button{background:${color(c)};color:#fff;border:0;font-weight:700;cursor:pointer;margin-top:.8rem}.row button{width:auto;margin:.3rem .3rem 0 0;padding:.3rem .7rem}.card{border:1px solid #e5e7eb;border-radius:10px;padding:.8rem 1rem;margin:.7rem 0}.note{font-size:.85rem;color:#4b5563}</style></head><body>${body}</body></html>`;

const day = (t) => new Date(t).toISOString().slice(0, 10);

export function renderChangelog({ entries, company, color: c, publicUrl }) {
  const head = `<link rel="alternate" type="application/atom+xml" href="${esc(publicUrl)}/feed.xml" title="${esc(company)} changelog"><link rel="alternate" type="application/feed+json" href="${esc(publicUrl)}/feed.json"><link rel="canonical" href="${esc(publicUrl)}/changelog">`;
  return shell(c, `${company} changelog`, `<h1>${esc(company)} changelog</h1><p class="note">Subscribe: <a href="${esc(publicUrl)}/feed.xml">Atom</a> &middot; <a href="${esc(publicUrl)}/feed.json">JSON Feed</a></p>
${entries.map((e) => `<article class="e" id="${esc(e.id)}"><div class="m"><span class="tag">${esc(e.tag)}</span>${day(e.publishAt)}</div><h2>${esc(e.title)}</h2>${renderMarkdown(e.body)}</article>`).join("") || "<p>Nothing published yet.</p>"}`, head);
}

// The admin page holds no secrets: it asks for the admin key in the browser and calls the API.
export function renderAdmin({ company, color: c }) {
  return shell(c, `Changelog · ${company}`, `<h1>${esc(company)} changelog admin</h1><label for="k">Admin key</label><input id="k" type="password" autocomplete="off"><button id="go" type="button">Load</button>
<div class="card"><label for="ti">Title</label><input id="ti" maxlength="120"><label for="tg">Type</label><select id="tg"><option>new</option><option>improved</option><option>fixed</option><option>removed</option><option>security</option><option>announcement</option></select>
<label for="bo">Body (Markdown subset: **bold**, *italic*, \`code\`, [link](https://...), "- " lists, "## " headings)</label><textarea id="bo" rows="6" maxlength="4000"></textarea>
<label for="wh">Publish at (optional, e.g. 2026-11-01T09:00:00Z; leave empty for now)</label><input id="wh"><label style="font-weight:400"><input type="checkbox" id="dr" style="width:auto"> Save as draft</label><button id="add" type="button">Add entry</button></div>
<div id="out"></div><p class="note">Entries are shown exactly as written. Drafts and future-dated entries are not public.</p>
<script>
var out=document.getElementById("out");
function el(t,x){var e=document.createElement(t);if(x)e.textContent=x;return e}
function call(m,p,b){return fetch(p,{method:m,headers:{authorization:"Bearer "+document.getElementById("k").value},body:b?JSON.stringify(b):undefined}).then(function(r){return r.json()})}
function load(){call("GET","/v1/entries").then(function(list){out.textContent="";if(!Array.isArray(list)){out.appendChild(el("p","Wrong key."));return}
list.forEach(function(t){var c=el("div");c.className="card";var live=t.status==="published"&&t.publishAt<=Date.now();c.appendChild(el("strong",t.title+" · "+t.tag+" · "+(t.status==="draft"?"draft":live?"live":"scheduled")+" · "+new Date(t.publishAt).toISOString().slice(0,10)));c.appendChild(el("p",t.body));
var row=el("div");row.className="row";var tog=el("button",t.status==="draft"?"Publish":"Make draft");tog.type="button";tog.onclick=function(){call("POST","/v1/entries/"+t.id,{status:t.status==="draft"?"published":"draft"}).then(load)};row.appendChild(tog);
var del=el("button","Delete");del.type="button";del.onclick=function(){if(confirm("Delete this entry?"))call("DELETE","/v1/entries/"+t.id).then(load)};row.appendChild(del);c.appendChild(row);out.appendChild(c)})})}
document.getElementById("go").onclick=load;
document.getElementById("add").onclick=function(){var b={title:document.getElementById("ti").value,body:document.getElementById("bo").value,tag:document.getElementById("tg").value};var w=document.getElementById("wh").value;if(w)b.publishAt=w;if(document.getElementById("dr").checked)b.status="draft";
call("POST","/v1/entries",b).then(function(r){if(r.error){alert(r.error);return}document.getElementById("ti").value="";document.getElementById("bo").value="";load()})};
</script>`, "", '<meta name="robots" content="noindex">');
}

server.mjs.text:
#!/usr/bin/env node
// Self-hosted changelog: public page, Atom + JSON feeds, embeddable "What's new" bell. Zero dependencies.
//   ADMIN_KEY=... PUBLIC_URL=https://changelog.example.com COMPANY_NAME=Acme node server.mjs
import http from "node:http";
import fs from "node:fs";
import { randomBytes, timingSafeEqual } from "node:crypto";
import { newState, createEntry, updateEntry, remove, publicEntries, stats, plainText, isPublic } from "./store.mjs";
import { toAtom, toJsonFeed } from "./feed.mjs";
import { renderChangelog, renderAdmin } from "./page.mjs";
import { widgetSource } from "./widget.mjs";

export { newState };
const env = process.env;

const readBody = (req, max = 20_000) => new Promise((resolve, reject) => {
  let size = 0; const chunks = [];
  req.on("data", (c) => { size += c.length; if (size > max) { reject(Object.assign(new Error("too large"), { status: 413 })); req.destroy(); } else chunks.push(c); });
  req.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
  req.on("error", reject);
});
const bearerOk = (req, key) => {
  const a = Buffer.from(req.headers.authorization || ""), b = Buffer.from(`Bearer ${key}`);
  return Boolean(key) && a.length === b.length && timingSafeEqual(a, b);
};

// cfg: {state, save, adminKey, publicUrl, company, color, notify, now}
export function handler(cfg) {
  const now = cfg.now || Date.now;
  const company = cfg.company || "Our team";
  const meta = { publicUrl: cfg.publicUrl, company };
  return async (req, res) => {
    const url = new URL(req.url, "http://x");
    const send = (code, body, type = "application/json", extra = {}) => {
      res.writeHead(code, { "content-type": type, "cache-control": "no-store", "referrer-policy": "no-referrer", "x-content-type-options": "nosniff", ...extra });
      res.end(typeof body === "string" ? body : JSON.stringify(body));
    };
    const fail = (code, error) => send(code, { error });
    const html = (code, body, csp = "default-src 'none'; style-src 'unsafe-inline'; frame-ancestors 'none'") => send(code, body, "text/html; charset=utf-8", { "content-security-policy": csp });
    const pub = { "access-control-allow-origin": "*", "cache-control": "public, max-age=60" };
    try {
      if (url.pathname === "/healthz") return send(200, "ok\n", "text/plain");
      if (url.pathname === "/embed.js" && req.method === "GET") return send(200, widgetSource(), "text/javascript; charset=utf-8", { "cache-control": "public, max-age=3600" });
      if ((url.pathname === "/" || url.pathname === "/changelog") && req.method === "GET") {
        const tag = url.searchParams.get("tag") || undefined;
        return html(200, renderChangelog({ entries: publicEntries(cfg.state, now(), { limit: 200, tag }), company, color: cfg.color, publicUrl: cfg.publicUrl }));
      }
      if (url.pathname === "/feed.xml" && req.method === "GET") return send(200, toAtom(publicEntries(cfg.state, now(), { limit: 50 }), meta), "application/atom+xml; charset=utf-8", pub);
      if (url.pathname === "/feed.json" && req.method === "GET") return send(200, toJsonFeed(publicEntries(cfg.state, now(), { limit: 50 }), meta), "application/feed+json; charset=utf-8", pub);
      if (url.pathname === "/entries.json" && req.method === "GET") {
        const limit = Math.max(1, Math.min(50, Number(url.searchParams.get("limit")) || 10));
        return send(200, publicEntries(cfg.state, now(), { limit, tag: url.searchParams.get("tag") || undefined }).map((e) => ({ id: e.id, title: e.title, tag: e.tag, publishAt: e.publishAt, text: plainText(e.body) })), "application/json", pub);
      }
      if (url.pathname === "/admin" && req.method === "GET") return html(200, renderAdmin({ company, color: cfg.color }), "default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; connect-src 'self'; frame-ancestors 'none'");

      if (url.pathname.startsWith("/v1/")) {
        if (!bearerOk(req, cfg.adminKey)) return fail(401, "admin key required");
        if (req.method === "GET" && url.pathname === "/v1/summary") return send(200, stats(cfg.state, now()));
        if (url.pathname === "/v1/entries") {
          if (req.method === "GET") return send(200, [...cfg.state.entries].sort((a, b) => b.publishAt - a.publishAt).slice(0, 500));
          if (req.method === "POST") {
            const out = createEntry(cfg.state, JSON.parse((await readBody(req)) || "{}"), { id: randomBytes(6).toString("hex"), now: now() });
            if (out.error) return fail(400, out.error);
            cfg.save();
            if (cfg.notify && isPublic(out.entry, now())) cfg.notify(out.entry).catch((e) => console.error("notify failed:", e.message));
            return send(201, out.entry);
          }
        }
        const m = url.pathname.match(/^\/v1\/entries\/([a-f0-9]+)$/);
        if (m && req.method === "POST") {
          const out = updateEntry(cfg.state, m[1], JSON.parse((await readBody(req)) || "{}"), now());
          if (out.error) return fail(out.error.startsWith("no such") ? 404 : 400, out.error);
          cfg.save(); return send(200, out.entry);
        }
        if (m && req.method === "DELETE") {
          const out = remove(cfg.state, m[1]);
          if (out.error) return fail(404, out.error);
          cfg.save(); return send(200, out);
        }
      }
      return send(404, "not found\n", "text/plain");
    } catch (e) {
      console.error("request failed:", e.message);
      return send(e.status && e.status < 500 ? e.status : e instanceof SyntaxError ? 400 : 500, { error: e instanceof SyntaxError ? "invalid JSON" : "Something went wrong." });
    }
  };
}

function readJson(path, fallback) {
  try { return JSON.parse(fs.readFileSync(path, "utf8")); } catch (e) { if (e.code === "ENOENT") return fallback; throw e; }
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const missing = ["ADMIN_KEY", "PUBLIC_URL"].filter((k) => !env[k]);
  if (missing.length) { console.error(`missing env: ${missing.join(", ")}`); process.exit(1); }
  const statePath = env.STATE || "state.json";
  const state = Object.assign(newState(), readJson(statePath, {}));
  const save = () => { fs.writeFileSync(`${statePath}.tmp`, JSON.stringify(state)); fs.renameSync(`${statePath}.tmp`, statePath); };
  const notify = env.NOTIFY_WEBHOOK ? async (e) => {
    const r = await fetch(env.NOTIFY_WEBHOOK, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ text: `${env.COMPANY_NAME || "Changelog"}: ${e.title} (${e.tag}) ${env.PUBLIC_URL}/changelog#${e.id}` }) });
    if (!r.ok) throw new Error(`webhook ${r.status}`);
  } : null;
  const cfg = { state, save, adminKey: env.ADMIN_KEY, publicUrl: env.PUBLIC_URL.replace(/\/$/, ""), company: env.COMPANY_NAME, color: env.BRAND_COLOR, notify };
  http.createServer(handler(cfg)).listen(Number(env.PORT || 8080), () => console.log(`changelog-keeper on :${env.PORT || 8080}`));
}

store.mjs.text:
// Changelog rules. Pure functions over a plain-object state; no I/O.
// The server, the feeds and the landing-page demo all use this file.

export const LIMITS = { title: 120, body: 4000, maxEntries: 2000 };
export const TAGS = ["new", "improved", "fixed", "removed", "security", "announcement"];

export const newState = () => ({ entries: [] });

const clean = (s, max) => String(s ?? "").replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f‪-‮⁦-⁩]/g, "").trim().slice(0, max);

export const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);

function parseWhen(v, fallback) {
  if (v === undefined || v === null || v === "") return fallback;
  const t = typeof v === "number" ? v : Date.parse(v);
  return Number.isFinite(t) && t > 0 && t < 4102444800000 ? t : null;
}

// status "draft" is never public; "published" goes public once publishAt has passed,
// which is how a release note is scheduled for a launch.
export function createEntry(state, input, { id, now }) {
  const title = clean(input.title, LIMITS.title), body = clean(input.body, LIMITS.body);
  if (!title) return { error: "title is required" };
  if (!body) return { error: "body is required" };
  const tag = input.tag === undefined || input.tag === "" ? "new" : String(input.tag);
  if (!TAGS.includes(tag)) return { error: `tag must be one of ${TAGS.join(", ")}` };
  const status = input.status === undefined || input.status === "" ? "published" : String(input.status);
  if (!["draft", "published"].includes(status)) return { error: "status must be draft or published" };
  const publishAt = parseWhen(input.publishAt, now);
  if (publishAt === null) return { error: "publishAt must be a date" };
  if (state.entries.length >= LIMITS.maxEntries) return { error: "entry limit reached" };
  const entry = { id, title, body, tag, status, publishAt, createdAt: now, updatedAt: now };
  state.entries.push(entry);
  return { entry };
}

export function updateEntry(state, id, input, now) {
  const e = state.entries.find((x) => x.id === id);
  if (!e) return { error: "no such entry" };
  const next = { ...e };
  if (input.title !== undefined) next.title = clean(input.title, LIMITS.title);
  if (input.body !== undefined) next.body = clean(input.body, LIMITS.body);
  if (input.tag !== undefined) next.tag = String(input.tag);
  if (input.status !== undefined) next.status = String(input.status);
  if (input.publishAt !== undefined) next.publishAt = parseWhen(input.publishAt, e.publishAt);
  if (!next.title || !next.body) return { error: "title and body cannot be empty" };
  if (!TAGS.includes(next.tag)) return { error: `tag must be one of ${TAGS.join(", ")}` };
  if (!["draft", "published"].includes(next.status)) return { error: "status must be draft or published" };
  if (next.publishAt === null) return { error: "publishAt must be a date" };
  Object.assign(e, next, { updatedAt: now });
  return { entry: e };
}

export function remove(state, id) {
  const i = state.entries.findIndex((x) => x.id === id);
  if (i < 0) return { error: "no such entry" };
  state.entries.splice(i, 1);
  return { ok: true };
}

export const isPublic = (e, now) => e.status === "published" && e.publishAt <= now;

// Public view: published and due, newest first.
export function publicEntries(state, now, { limit = 50, tag } = {}) {
  return state.entries.filter((e) => isPublic(e, now) && (!tag || e.tag === tag))
    .sort((a, b) => b.publishAt - a.publishAt || (a.id < b.id ? 1 : -1)).slice(0, limit);
}

export function stats(state, now) {
  const s = { total: state.entries.length, published: 0, scheduled: 0, draft: 0, latest: null };
  for (const e of state.entries) {
    if (e.status === "draft") s.draft++; else if (e.publishAt > now) s.scheduled++; else { s.published++; if (!s.latest || e.publishAt > s.latest) s.latest = e.publishAt; }
  }
  return s;
}

// A small, safe Markdown subset: paragraphs, "## " headings, "- " lists, **bold**, *italic*,
// `code` and [text](https://...) links. Everything is escaped first, so entry text can
// never inject markup; only http(s) links are allowed.
function inline(raw) {
  let s = esc(raw);
  s = s.replace(/`([^`]+)`/g, "<code>$1</code>");
  s = s.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
  s = s.replace(/(^|[^*])\*([^*\s][^*]*)\*/g, "$1<em>$2</em>");
  s = s.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, '<a href="$2" rel="noopener nofollow ugc">$1</a>');
  return s;
}

export function renderMarkdown(body) {
  return String(body ?? "").replace(/\r\n?/g, "\n").split(/\n{2,}/).map((block) => {
    const lines = block.split("\n").filter((l) => l.trim());
    if (!lines.length) return "";
    if (lines.every((l) => /^\s*[-*] /.test(l))) return `<ul>${lines.map((l) => `<li>${inline(l.replace(/^\s*[-*] /, ""))}</li>`).join("")}</ul>`;
    if (/^#{1,3} /.test(lines[0]) && lines.length === 1) return `<h3>${inline(lines[0].replace(/^#{1,3} /, ""))}</h3>`;
    return `<p>${lines.map(inline).join("<br>")}</p>`;
  }).join("");
}

// Plain text for the widget, which never renders HTML.
export const plainText = (body) => String(body ?? "").replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, "$1 ($2)").replace(/(\*\*|`|^#{1,3} |^\s*[-*] )/gm, "").replace(/\*([^*\n]+)\*/g, "$1");

