const KEY = "changelog-keeper-usage";
// Separate from the counters on purpose: opting out *removes* the
// counters, so a flag stored inside them would be deleted by the very
// act it records.
const OPT_OUT = "changelog-keeper-usage-opt-out";

// The in-memory flag is only a same-page fast path. `globalThis` is a
// fresh realm on every page load, so without the stored key the switch
// silently stops working on the visitor's next visit -- and they do not
// look again, because they believe they already used it.
function usageOptedOut() {
  if (globalThis.__usageOptOut) return true;
  try {
    return typeof localStorage !== "undefined" && localStorage.getItem(OPT_OUT) === "1";
  } catch {
    // A blocked or full store must never be read as consent.
    return false;
  }
}

function usageBlocked() {
  if (usageOptedOut()) return true;
  try {
    if (navigator.doNotTrack === "1" || navigator.globalPrivacyControl) return true;
  } catch {
    /* navigator is optional in tests */
  }
  return false;
}

export function record(event) {
  if (typeof localStorage === "undefined" || usageBlocked()) return;
  let current;
  try {
    current = JSON.parse(localStorage.getItem(KEY) || "{}");
  } catch {
    current = {};
  }
  if (!current || typeof current !== "object" || Array.isArray(current)) current = {};
  current[event] = (current[event] || 0) + 1;
  try {
    localStorage.setItem(KEY, JSON.stringify(current));
  } catch {
    /* storage is optional */
  }
}

export function readUsage() {
  if (typeof localStorage === "undefined") return {};
  try {
    const parsed = JSON.parse(localStorage.getItem(KEY) || "{}");
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {};
  } catch {
    return {};
  }
}

export function setUsageOptOut(value) {
  const off = Boolean(value);
  globalThis.__usageOptOut = off;
  if (typeof localStorage === "undefined") return;
  if (off) {
    try { localStorage.removeItem(KEY); } catch { /* storage is optional */ }
    try { localStorage.setItem(OPT_OUT, "1"); } catch { /* storage is optional */ }
  } else {
    try { localStorage.removeItem(OPT_OUT); } catch { /* storage is optional */ }
  }
}

export { usageOptedOut };

widget.mjs.text:
// The embeddable "What's new" bell (served at /embed.js). It renders with textContent only,
// inside a shadow root, so an entry can never inject markup or restyle the host page.
// The only thing it remembers is the time of the newest entry the visitor opened, in
// localStorage on the visitor's own browser; nothing is sent back to the server.
export function widgetSource() {
  return `(function () {
  var s = document.currentScript; if (!s) return;
  var base = new URL(s.src).origin, dark = s.getAttribute("data-theme") === "dark";
  var limit = Math.max(1, Math.min(20, Number(s.getAttribute("data-limit")) || 5));
  var key = "changelog-keeper-seen:" + base;
  function seen() { try { return Number(localStorage.getItem(key)) || 0; } catch (e) { return 0; } }
  function mark(t) { try { localStorage.setItem(key, String(t)); } catch (e) {} }
  var host = document.createElement("div"); s.parentNode.insertBefore(host, s.nextSibling);
  var root = host.attachShadow ? host.attachShadow({ mode: "open" }) : host;
  var bg = dark ? "#1f2937" : "#fff", fg = dark ? "#f3f4f6" : "#111827", line = dark ? "#374151" : "#e5e7eb";
  var css = document.createElement("style");
  css.textContent = ".b{position:relative;font:15px/1.4 system-ui,sans-serif;background:" + bg + ";color:" + fg + ";border:1px solid " + line + ";border-radius:999px;padding:6px 14px;cursor:pointer}" +
